export default function domain({ domain }) {
  if (
    typeof domain !== "string" ||
    domain.length > 253 ||
    !domain ||
    !domain.split(".").every((x) => /^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/i.test(x)) ||
    !domain.includes(".")
  )
    throw Error("Enter a valid domain name without protocol or port");
  return {
    domain: domain.toLowerCase(),
    body: { processor: "get-domain-certificate", params: { domain: domain.toLowerCase() } },
  };
}

