export default function certificate({ body, domain }) {
  const valid = body?.message?.valid;
  if (valid !== true && valid !== false && valid !== "true" && valid !== "false")
    throw Error("Uproc did not return certificate validity");
  return {
    invalid: valid === false || valid === "false",
    text: "The certificate for " + domain + " is outside its validity date range.",
  };
}
